-- Rifts World Book 3: England - its bestiary and its notable NPCs.
-- 8 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~277-england-creatures-b.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('temporal-raider', 'Temporal Raider', 'alien', 'rifts', 1, 'Unprincipled, Anarchist or any evil; typically Miscreant, Diabolic or Anarchist', '{"IQ":"2D6+10","ME":"2D6+10","MA":"3D6","PS":"3D6+10","PP":"3D6+6","PE":"3D6+6","PB":"2D6","Spd":"3D6+10"}', NULL, NULL, '6D6x10', '3D6x10', '6D6', 'Mega-Damage creature: M.D.C./Hit Points 6D6x10. P.P.E. is 3D6x10 plus 20 per level of experience; I.S.P. is 6D6 plus 1D6 per level (both stored at level one). P.S. is supernatural. Bio-regenerates 4D6 M.D.C. once a melee round at the cost of one melee action. Average Level of Experience (NPC) 1D6+6; NPCs are 7th to 12th level.', NULL, 13, '{"attacks":5,"initiative":6,"strike":5,"parry":7,"dodge":7}', '+5 to strike hand to hand, +6 to strike with energy blasts, +7 to parry and dodge, +6 on initiative, +5 to roll with punch, +5 to pull punch, +3 to save vs psionics, +3 to save vs all magic, +7 to save vs Horror Factor. Five hand to hand or psionic attacks per melee, or ten light or five heavy energy blasts, or two magic attacks; one more hand to hand attack at levels 11 and 15. A player character starts with three hand to hand or psionic attacks and one magic attack, gains one of each at level 4 and another hand to hand attack at levels 7, 11 and 15, and has half bonuses until level 6.', 'R.C.C. Skills: understands the principles of magic, recognizes enchanted items (10% per level), Land Navigation (+20%), Wilderness Survival (+10%), Pilot Hover Vehicles (+10%), Pilot Jet Aircraft (+10%), Horsemanship (often a robot horse, +10%), Language: Dragonese and three of choice, Climb (+10%), W.P. Energy Pistol, W.P. Energy Rifle and three other W.P. of choice. Secondary Skills: ten from any category without restriction, plus two at levels 4, 8 and 12.', 'Senses rifts opening, closing and where they are within 50 miles (80 km), as a ley line walker does, and within one mile (1.6 km) senses envelopes, portals, dimensional teleports and time holes too. Sees dimensional envelopes and pockets, fourth- and two-dimensional beings, astral travelers and the unseen essences of alien intelligences and entities. Ley line phasing as a temporal wizard. Energy blasts from hands (1000 ft/305 m), eyes or mouth (500 ft/153 m). An energy vampire that needs no air, food or drink: by touch it drains 15 S.D.C. (then hit points) per melee round, must take 1000 S.D.C./hit points or 10 M.D.C. a day, can store six days of it, and starves without it. Poison, toxins, drugs, gas, heat and fire cannot harm it; all energy, M.D. blasts and magic included, does half damage. Sees radiation and infrared, heat (thermal imaging 600 ft/183 m), nightvision 600 ft (183 m), and is not blinded by a sun. Leaps 20 ft (6 m) up and 15 ft (4.6 m) across from a standstill, 10 ft more running.', 'NPC: every temporal magic spell, all summoning magic, Protection Circle: Simple and Superior, Tongues, Eyes of Thoth, Shadow Meld, Time Slip, Negate Magic, Mystic Portal, Close Rift, Dimensional Portal, Teleport and Teleport: Superior, plus 12 spells of levels 1-8; two more conventional spells of any level from level 9. Player character: ten temporal spells of choice, Tongues, Sense Magic, Time Slip, Shadow Meld, Teleport: Lesser, Mystic Portal, Protection Circle: Lesser, Summon and Control Canines, Summon and Control Rodents, Close Rift and Dimensional Portal; each new level adds one temporal spell of any level and two conventional spells of levels 1-8. P.P.E. 3D6x10 plus 20 per level.', 'Minor psionic: Alter Aura, Death Trance, Levitation, Mind Block and two Sensitive powers of choice. I.S.P. 6D6 plus 1D6 per level.', '8 feet (2.4 m) tall', 'About 700 lbs (315 kg)', 'Unknown; thought to be 10,000 years or more', 'Travels the dimensions; found wherever fortune and power can be had', 'Occasionally takes a human apprentice in temporal magic (the temporal wizard and temporal warrior)', 'The Splugorth and their minions; most dimensional travelers and practitioners of magic distrust it', 'Optional R.C.C. or N.P.C. (p.71-73); the stat block itself advises it as a villain and leaves player use to the Game Master. A player character starts at level 1 or 2 with 2D6x10,000 credits or the same in gems. NPCs hide 1D6 treasure troves in different dimensions and carry about 1D6 million credits. Cybernetics: none, totally incompatible. Ruling D19 gives it a class as well as this row.', 'A demonic-looking alien energy being in a humanoid, armor-plated mega-damage body, master of dimensional and temporal magic. It lives on the life energy of others and often kills for the pleasure of it. Greedy, treacherous and a superb tactician, it raids even the Splugorth and godlings by surprise, though it can work within a group for a shared aim. Raiders admire human ferocity and sometimes teach their art to apprentices bound to six years of service and secrecy; many become warlords, guild heads, royal advisers or kings, yet seldom stay anywhere past a generation or two. Bald and hairless, its head looks like a mask of brushed silver metal and metal-like plates cover its fingers, forearms, neck and chest; its skin is light grey or blue-grey, and it favors dark clothing with a splash of color and a cape.', 'Rifts World Book 3: England p.71-73'),
('zllyphan-energy-being', 'Zllyphan Energy Being', 'entity', 'rifts', 0, 'Any, but usually Anarchist or evil', '{"IQ":"3D6+12","ME":"3D6+12","MA":"3D6+10","PB":"3D6+6"}', NULL, NULL, '1D4x10000', '2D6x1000', '1D4x1000', 'The average Zllyphan alien intelligence. Mega-damage energy creature: M.D.C. 1D4x10,000. At zero it is hurt but not destroyed and drops to two physical or psionic attacks and one magic attack with no combat or save bonuses; it dies only at -500. P.S., P.P. and P.E. are not applicable. Spd is flight at 4D6x10 mph, not rolled here. Bio-regenerates 2D6x100 M.D.C. an hour. Average Experience Level 2D4+4.', NULL, 16, '{"attacks":6,"initiative":6,"strike":6}', 'Same as Zazshan: +6 on initiative, +6 to strike with energy blasts, an automatic dodge that works like a parry, +6 to save vs Horror Factor, +1 to spell strength, +2 on all saving throws; impervious to mind control, even by vampires. Six energy blasts, five psionic attacks or two magic attacks per melee.', 'As Zazshan: magic, psionics, possession and subterfuge; human skills are left to minions and life essences. Magic lore (runes, mystic symbols, circles, wards, enchantment, magic items) and ley line, stone master and spell casting knowledge at 90%; Dragonese/Elf, Faerie Speak and Gobblely 98%; Basic and Advanced Math, Demon Lore and Faerie Lore 98%.', 'As Zazshan (p.85-86): nightvision 1000 ft (310 m), sees the invisible, unharmed by cold, heat, fire, gas, drugs or poison, and breathes no air. Dimensional teleport (98%) to any world where it holds life essences, and can open a rift with its own P.P.E. to anywhere it has been. Possesses and reanimates the dead, teleports itself up to 600 miles (960 km), and as often as three times a day rifts in 2D4 greater or 6D6 lesser essence minions. It splinters itself into life essences that live in human bodies (Mrrlyn and the supreme nexus knights are such). Magic weapons, psionics, supernatural beings and creatures of magic do full damage, and Millennium Tree wands, staves and weapons do triple. It must feed on large amounts of magic energy and must move on if that source fails.', 'As Zazshan: all ley line walker powers and spells, stone master powers (Rifts Atlantis) and the temporal spells Time and Space Teleportation, Time Barrier, Time Maelstrom, Time Capsule and Time Warp: Age. P.P.E. 2D6x1000.', 'As Zazshan: Telepathy, Empathy, See Aura, Sense Magic and all Physical and Super-Psionic powers. I.S.P. 1D4x1000.', 'A sphere of energy the size of a house', 'None; an energy being', 'Ancient; Zazshan is 120,000 years old', 'Its home dimension; reaches Earth through a controlled nexus (Zazshan holds one in Somerset, near New Camelot)', 'Its own splintered life essences and summoned minions', 'The Splugorth, ancient rivals of its race', 'None; an alien intelligence, not a player character. Zazshan (p.85-86) is the named one and is not this row. Bionics and bio-technology: totally incompatible.', 'The average member of the Zllyphan race (pronounced Zil-lee-fan), alien intelligences much like Zazshan, the mind behind Mrrlyn. It appears as a house-sized globe of blue and white energy with what looks like electricity crawling over it. Zllyphan straddle dimensions without fully coming through, feed on magic energy and work through puppets and splintered pieces of themselves, playing long games of conquest; their race and the Splugorth have long used other peoples as pieces in contests against each other.', 'Rifts World Book 3: England p.85-86'),
('supreme-nexus-knight', 'Supreme Nexus Knight', 'entity', 'rifts', 0, 'Any, but usually Anarchist or evil; most are Miscreant and use Alter Aura to pass as Scrupulous', '{"IQ":"16","ME":"15","MA":"11","PS":"2D6+14","PP":"3D6+6","PE":"2D6+14","PB":"3D6","Spd":"4D6"}', NULL, NULL, '4D6x10', '2D6x10', '3D4x10', 'A lesser Zllyphan life essence in a human body. Mental attributes are the printed SN-knight figures (I.Q. 16, M.A. 11, M.E. 15); the printed knight also has P.S. 24, P.P. 19, P.E. 24, P.B. 9, Spd 18, 180 M.D.C., 80 P.P.E. and 80 I.S.P., while any lesser life essence rolls the dice stored here. Supernatural strength and endurance; bio-regenerates 4D6 M.D.C. an hour. Destroying the body hurls the essence home for 2D6 months. Usually wears 100 M.D.C. demon armor, subtracted first. SN-knights are all 5th level (lesser essences 3rd to 6th).', NULL, 11, '{"attacks":4,"initiative":5,"strike":5,"dodge":5}', '+5 on initiative, +5 to strike hand to hand, +2 to strike with an energy weapon, +5 to dodge, +5 to save vs Horror Factor, +1 on all saving throws; impervious to mind control, even by vampires. Four hand to hand or psionic attacks per melee, or by magic.', 'Magic Knowledge at 70% (runes, wards, enchantment, magic items, mystic symbols, magic circles); Dragonese/Elf, Faerie Speak and Gobblely 98%, and up to four local languages. Printed SN-knight: Basic and Advanced Math 93%, Demon and Monster Lore 93%, Faerie Lore 93%, Disguise 45%, Escape Artist 50%, Intelligence 49%, Tracking 40%, Wilderness Survival 45%, Climb 55/45%, Prowl 45%, Pick Locks 50%, Streetwise 37%, Swim 65%, Pilot Hover Vehicles 65%, Horsemanship 52%. A lesser essence may learn up to 12 skills plus math and lore at its level; only magic, cunning and deception skills get +5%.', 'Nightvision 100 ft (30.5 m), sees the invisible, cold, heat and fire do half damage, impervious to gases, drugs and poison. Its borrowed human body eats about half as much as a human, needs about five hours of rest a day and tires at half the human rate, and lasts about ten times as long (about 700 years). Dimensional teleport (80%) between its home dimension and the world it occupies, and reanimates the dead as the greater essences do. Magic weapons, psionics, supernatural beings and creatures of magic do normal damage; Millennium Tree wands, staves and weapons do triple. Cannot be magically transformed, though illusions such as Mask of Deceit work. Conjures a psi-sword and psi-shield at will.', 'All conventional spell magic of levels 1-15 as a 5th level caster, but only 80 P.P.E. (a lesser essence rolls 2D6x10); no temporal or stone magic.', 'Major psionic, 5th level: Telepathy, Empathy, See Aura, Sense Magic, all Physical powers and three Super-Psionic powers chosen for life; SN-knights all take Mind Block Auto-Defense, Psi-Shield and Psi-Sword. I.S.P. 80 (a lesser essence rolls 3D4x10).', 'About 6 feet (1.8 m) tall', 'As its human host', 'The host body lasts about 700 years before a new one is needed', 'New Camelot and the British Isles, in the service of Mrrlyn; 50 serve as nexus knights', 'Mrrlyn, whom they serve with total loyalty, and the alien intelligence Zazshan', 'Whoever Mrrlyn names an enemy of New Camelot; resented by many Knights of Camelot', 'None; an NPC life essence (The Many Faces of Mrrlyn, p.91-93). Carries 1D6x10,000 credits for bribes and supplies. Bionics: a rarity. The human nexus knight on p.99 is a separate block, left by ruling D22.', 'The supreme nexus knights (SN-knights) are lesser life essences split off Zazshan and set in human or human-looking bodies, loyal only to Mrrlyn. They lead his elite nexus knights and act as New Camelot''s feared secret police: gruff, forceful and quick to strike before asking, they answer to Mrrlyn before the King and tell high-ranking knights nothing of their orders. They wear frilled, horned demon armor marked with Mrrlyn''s M and demon crest, and when no one is watching they fight on long after a human would fall, silencing those who see it.', 'Rifts World Book 3: England p.91-93'),
('ghost-knight', 'Ghost Knight', 'entity', 'rifts', 0, 'Miscreant', '{"IQ":"10","ME":"10","MA":"10","PS":"36","PP":"10","Spd":"30"}', NULL, NULL, '100', '10', '20', 'A tectonic entity animating a suit of supreme nexus knight armor: the armor shell has 100 M.D.C., and destroying it frees the entity and sends it home. Typical attributes are printed as fixed figures; P.E. and P.B. are not applicable; Spd 30 is about 20 mph (32 km). Supernatural strength. I.S.P. base 20, and it can turn available P.P.E. into I.S.P. at four I.S.P. per point. Always 4th level.', NULL, 14, '{"attacks":4,"initiative":1,"strike":2,"parry":2,"dodge":2}', '+1 on initiative, +2 to strike, parry and dodge, critical strike on an unmodified 20, +1 to save vs psionics, +2 to save vs magic, +10 to save vs Horror Factor. Four hand to hand or three psionic attacks per melee.', 'None as such; rides a horse about 52% and Land Navigation 48%. Communicates by empathy and gesture, or by telepathy with Mrrlyn.', 'Impervious to poison, toxins, drugs and gases, heat, fire and cold; normal vision. As a tectonic entity it flies in energy form and possesses and animates inanimate objects (Rifts Conversion Book p.178). Under Mrrlyn''s full control on British soil; beyond Britain it acts more freely and more viciously.', 'None. P.P.E. 10.', '4th level: Empathy, Mind Block, Presence Sense, See the Invisible, See Aura, Sixth Sense, Telepathy and Telekinesis. I.S.P. 20 base.', 'A suit of man-sized SN-knight armor', 'As its armor', 'Not stated; Mrrlyn replaces them easily', 'The British Isles, sent out in pairs and fours from New Camelot', 'Mrrlyn, to whom it answers directly', 'Aliens, dragons, monsters and anyone hostile to New Camelot', 'None; Mrrlyn''s conjured troops. Known only by number (N-5, N-73); about 80 serve, of up to 120 he can control. Rides a bionic horse.', 'About a quarter of Mrrlyn''s nexus knights look like empty suits of armor moving on their own, and they are: tectonic entities, normally chaotic and destructive spirits, bound into the frilled SN-knight armor (without the flaming sword). They show no feeling except fury in battle. Patrols question strange-looking travelers and dragons about who they are and why they have come, and any hostility brings an attack that ends only in surrender, capture or death; captives go to New Camelot for questioning.', 'Rifts World Book 3: England p.96-97'),
('fomorian', 'Fomorian', 'demon', 'rifts', 0, 'Anarchist, Miscreant or Diabolic', '{"IQ":"2D6+2","ME":"2D6+2","MA":"2D6+2","PS":"3D6+8","PP":"3D6+4","PE":"3D6+4","PB":"1D6+3","Spd":"4D6+12"}', NULL, NULL, '4D6x10', '1D4x10', NULL, 'Mega-Damage creature: 4D6x10 M.D.C., 90 to 140 being the usual range. Supernatural strength and endurance. Bio-regenerates 2D6 a melee. No I.S.P. Average Level of Experience 1D4+2; high druids, war chiefs and commanders 1D4+5. A few chiefs wear 100 M.D.C. armor (-10% prowl); 80% wear none.', NULL, 10, '{"attacks":5,"initiative":3,"strike":2,"parry":1,"dodge":1}', '+3 on initiative, +2 to strike, +1 to parry and dodge, +2 to roll with impact, critical strike on a natural 18-20, +1 to save vs magic, +2 to save vs poison, +5 to save vs Horror Factor, in addition to attribute and skill bonuses. Fights as Hand to Hand: Expert or Assassin; warriors below 7th level have five attacks per melee, 8th to 12th six, 13th to 15th seven.', 'Typical warrior, all at +10%: Hand to Hand: Expert or Assassin, Wrestling or Boxing, Climb, W.P. Sword, W.P. Knife, W.P. Targeting (throwing sticks, spears, slings), Track Humanoids, Land Navigation, Wilderness Survival, Horsemanship, Basic Math, Language: Dragonese, Gobblely and Faerie Speak. Four more from Physical, Pilot, Rogue or W.P. at levels 4, 8 and 12.', 'Nightvision 200 ft (61 m), sees the invisible, impervious to cold and normal fire (M.D. fire does half), expert swimmer, breathes no air and so stays underwater for hours and ignores toxic gas, and can change into a big black eel or serpent-like fish. Cannot come within 3000 ft of a Millennium Tree, and Millennium Tree weapons, magic and storms do double damage to it.', 'None, except the one in ten who are blood druids.', 'None.', '8 to 10 feet (2.4 to 3 m) tall', 'Not stated', '300 years', 'The Scottish Highlands, Orkney and the northern islands, nearly 100,000 strong and spreading into the lowlands; their home dimension, reached through the Stenness nexus, resembles Scotland', 'Whoever Bres and their leaders name', 'Every other race, which they fight, conquer or enslave; the people of the Tree of Ages', 'None; an NPC race. Warriors, with 10% blood druids, are their only two occupations. Favors swords, knives, spears, throwing sticks and slings, 40% now with energy rifles, and loves magic weapons; some ride ghostly white fomorii war-horses. Cybernetics: none. Nate''s ruling (2026-11-12) gives it this row and no class.', 'The Fomorii (also Fomhoire, Fo-Moir, Fomor, Fomorach; pronounced Foe more i ans): mega-damage giants most humans call demons, misshapen, grey-skinned, with one small eye set to one side, big teeth, a twisted left foot and often a hunched back. They came with beings claiming to be the old Celtic gods about a century ago, hold the Highlands and Orkney, and are massing to sweep south. Savage and cruel, they wreck, torture and kill for pleasure, wear their foes'' bones and badly mistreat their slaves, but fear intelligent magic creatures such as dragons and sphinxes.', 'Rifts World Book 3: England p.125-126'),
('ogeeyin', 'Ogeeyin', 'alien', 'rifts', 1, 'Any, but typically Principled or Scrupulous', '{"IQ":"2D6+16","ME":"2D6+16","MA":"2D6+12","PB":"2D4","Spd":"6D6"}', NULL, NULL, '1D4x100', '4D6x10', '4D6x10', 'Natural form. Mental attributes are rolled for EACH of the four minds sharing the one body; P.S., P.P. and P.E. are not applicable. Spd is float and flight in natural form (300 mph/482 km as an energy sphere). M.D.C.: 1D4x100 in natural form, 2D4x10 as an energy sphere. Each mind has 4D6x10 P.P.E. (plus 40 with all four present) and 4D6x10 I.S.P. (plus 120 with all four present; 150 to 200 is typical). Bio-regenerates 4D6 M.D.C. psionically. Average Level of Experience 1D4+3.', NULL, 10, '{"attacks":8,"initiative":8,"strike":4,"parry":4,"dodge":8}', 'Per lobe: +4 to strike, +4 to parry, +8 to dodge, +8 on initiative, +8 to roll with punch, +4 to save vs psionics, +4 to save vs all magic, +4 to save vs poison, +4 to save vs Horror Factor, +16% to find its way back from an astral journey. Each active mind has two physical, magic or psionic attacks, eight in all with four awake; physical attacks usually need ectoplasmic limbs.', 'R.C.C. Skills: Basic and Advanced Math (+20%) and Land Navigation (+20%), plus two comprehensive areas of knowledge per mind from Behavior, Machines, Medical, Piloting, Sciences, Spell Magic (four spells each of levels 1-6), Stone Magic, Technical, Weapons & Combat and Woodland. No secondary skills and no skill bonuses beyond I.Q.; skill level seldom passes 7th.', 'Four minds share one body, each a lobe that can leave as a basketball-sized energy sphere, teleport to a dimension it has watched from the astral plane, and within 24 hours build and bond with a body of stone or earth (the Guardian); its lobe sleeps meanwhile, and once back it cannot leave again for 4D6 days. The others always find it by astral projection and speak to it by telepathy. Impervious to poison, toxins, drugs and gases; lives on ambient magic and psionic energy without air, food or water; sees the invisible; nightvision 300 ft (91.5 m); fire and cold do half damage. Its antennae sense air movement like motion detectors, hear as amplified hearing and analyze smells molecularly: recognizes people and places by scent 65%, moves in darkness, tracks by scent 40%.', 'Varies with its areas of knowledge: Spell Magic gives four spells from each of levels 1-6, Stone Magic all stone master abilities (Rifts Atlantis).', 'Master psionic: all Sensitive powers, Detect Psionics, Bio-Regeneration (4D6 M.D.C.), Alter Aura, Death Trance, Ectoplasm, Mind Block and seven Super-Psionic powers of choice. I.S.P. 4D6x10 per mind.', 'A ball 10 feet (3 m) across', '700 lbs (315 kg)', '20,000+ years', 'Its home dimension, observing other worlds from the astral plane; one life node guards the Well of Wisdom in Rifts England', 'The minds of the golden table at the Well of Wisdom; good-aligned seekers who come to the Well', 'Would-be conquerors who try to seize or close the Well', 'Optional R.C.C. (p.142-144) in its natural form; uses no equipment. Cybernetics: none, incompatible. The Guardian form is its own row (ogeeyin-guardian). Ruling D19 gives it a class as well as this row.', 'A ten-foot ball of smooth pale pink or tan flesh, divided into four quarters, each with two antennae and four round life nodes, its underside fringed with foot-long black filaments. Each quarter is a separate mind with its own talents; together they study other worlds by astral projection. One Ogeeyin watched Earth through the Cataclysm for about fifty years, took pity on humankind and sent a life node to England, where with the minds of a golden table it raised the mound and tunnel of the Well of Wisdom and now guards it.', 'Rifts World Book 3: England p.142-143'),
('ogeeyin-guardian', 'Ogeeyin Guardian', 'alien', 'rifts', 0, 'As the Ogeeyin: any, but typically Principled or Scrupulous', '{"IQ":"2D6+16","ME":"2D6+16","MA":"2D6+12","PS":"4D6+12","PP":"2D6+10","Spd":"4D6"}', NULL, NULL, '2D4x100', '4D6x10', '4D6x10', 'Guardian form: one Ogeeyin life node in a stone or earth body. Mental attributes are unchanged from its natural form; P.E. is not applicable and P.B. is not printed. M.D.C. 2D4x100 for the stone body (400 or 500 typical); the energy essence inside has 2D4x10 M.D. and, if it loses all of it, is thrown back to its astral-plane body and cannot return for 1D6 months. Strikes do mega-damage. 150 to 200 I.S.P. is typical. Average Level of Experience 1D4+3.', NULL, 11, '{"attacks":5,"initiative":2,"strike":4,"parry":4,"dodge":4}', '+4 to strike, parry and dodge, +2 on initiative, +2 to roll with punch, +4 to pull punch, critical strike on an unmodified 19-20, mega-damage punches and kicks, +2 to save vs psionics, +2 to save vs all magic, +4 to save vs Horror Factor. Five hand to hand or psionic attacks per melee, or two magic attacks.', 'Unchanged from the Ogeeyin: Basic and Advanced Math (+20%), Land Navigation (+20%) and two comprehensive areas of knowledge.', 'Builds its stone or earth body in about an hour, bonded to every grain of it; if the body is destroyed it rebuilds in eight hours, and lost limbs or lesser damage in four. Its molecular control works on its own body only, which it can shape as a pillar or boulder. Sees the invisible, nightvision 300 ft (91.5 m), unharmed by heat, fire, cold, gas, drugs or poison, and needs no air, food or drink. Even inside the stone it can be reached by psionic exorcism, empathic transmission, mind wipe, mind bolts and mind control, and by magic exorcism, banishment, entity control, communing with spirits, the luck curse and illusions; an exorcism drives it out as an exposed energy being that has six hours to build a new body or is sent home for 1D6 months.', 'Varies; as its natural form''s areas of knowledge.', 'Master psionic: all Sensitive powers, Detect Psionics, Bio-Regeneration (4D6 M.D.C.), Alter Aura, Death Trance, Ectoplasm, Mind Block and seven Super-Psionic powers of choice. I.S.P. 4D6x10.', '7 to 10 feet (2.1 to 3 m) tall; humanoid, animal-like or monstrous, male or female', 'Three to six tons', '20,000+ years', 'The Well of Wisdom in Rifts England, which it guards', 'The minds of the golden table; good-aligned visitors to the Well', 'Those who would seize the Well or keep others from it', 'None as a separate class; the Guardian form of the Ogeeyin optional R.C.C. (p.144), whose natural form is the ogeeyin row. Uses no equipment. Cybernetics: none, incompatible.', 'The body an Ogeeyin life node builds for itself on another world: a giant stone figure, usually humanoid, made from the earth and rock around it and serving as both its anchor there and its weapon. At the Well of Wisdom in England the Guardian has long kept the Well open to anyone of good alignment.', 'Rifts World Book 3: England p.144'),
('chiang-ku-dragon-england', 'Chiang-Ku Dragon', 'dragon', 'rifts', 1, 'Any, but typically good or selfish; the Nog Henge are all good', '{"IQ":"3D6+12","ME":"3D6+12","MA":"3D6+12","PS":"3D6+12","PP":"2D6+10","PE":"2D6+10","PB":"2D6+10","Spd":"3D6+12"}', NULL, NULL, '4D4x100', '2D4x100+200', '3D4x10', 'Adult figures; M.D.C. 4D4x100 in human form, plus 1000 in its natural serpent form. Hatchling: I.Q., M.E., M.A., P.S. and Spd 3D6+4 each, P.P., P.E. and P.B. 2D6+3 each, M.D.C. 1D4x100 in human form plus 100 as a serpent, P.P.E. 2D4x10+20, Horror Factor 9. Bio-regenerates 1D4x10 M.D. every five minutes. Average Experience Level of an adult 1D6+7, on the Dragon experience table whatever its magic.', NULL, 13, '{"strike":1,"parry":2,"dodge":2}', 'Adult: +1 to strike, +2 to parry, +2 to dodge, +4 damage, +2 to roll with punch, critical strike on an unmodified 19-20, +1 to save vs psionics, +3 to save vs spell and illusionary magic, +1 to save vs circle magic, +4 to save vs Horror Factor. Hatchling: +1 melee attack, +1 to save vs all magic, +2 to save vs Horror Factor. Hand to Hand: Basic, or Expert or Martial Arts for two R.C.C. skills; attacks per melee vary with level, and tattoo or psionic attacks equal its hand to hand attacks. Tattoo masters add +1 to save vs all magic, +1 to save vs Horror Factor, +2 P.E. and recover P.P.E. twice as fast.', 'R.C.C. Skills: all Domestic, Basic Math (+10%), Art (+10%), Land Navigation, Wilderness Survival, Streetwise, Disguise (+5%), Holistic Medicine (+5%), Climbing (+10%), Faerie Lore (+15%), Demon & Monster Lore (+5%), two basic Pilot skills (+5%), three ancient and three modern W.P.; I.Q. bonus applies to all. Imitates a particular person or animal at 10% +5% per level.', 'Nightvision 90 ft (27.4 m) and sees the invisible; poison, toxins, drugs and gas cannot harm it, and fire and cold do half damage. The greatest shape changer of all dragons, even as a hatchling: it can become any living animal from a human to a raven, or mist, but not an object or an insect, no smaller than a cat and no larger than itself, and the shape holds indefinitely, through sleep and unconsciousness, until it chooses otherwise or falls into a coma or dies. A changed dragon keeps all its own powers and gains none of the copied form''s. Feels the presence of a ley line, a nexus or another dragon within 20 miles (32 km), by direction and rough distance only. No teleport and no breath weapon.', 'Born understanding magic, all tattoo magic (as the Splugorth; Rifts Atlantis) and the Elixir of Power and Deceit; knows no spells unless taught by a mage, on the Dragon experience table. Uses techno-wizard devices without instruction, reads magic, uses scrolls, recognizes circles, rune weapons and enchantment. Typical studies: tattoo master 50%, ley line walker 15%, stone master 10%, temporal wizard 10%, shifter/summoner 5%, diabolist 5%, other 5%. Tattoos on humans, elves, ogres and Chiang-Ku only. Marks of Heritage: Eye of Knowledge (all languages 96%, literate 82%) and Flaming Sword; one new tattoo at each even level. A tattoo master adds two magic and two simple weapon tattoos, the Rose of Healing and the Phoenix (super-healing and resurrection at a permanent cost to the dragon), a power tattoo every other level and another tattoo each level from 2nd. P.P.E. 2D4x100+200 adult.', 'Major psionic: seven powers from one of Sensitive, Healing or Physical, plus two from any of the three at levels 3, 6, 9 and 12; no Super-Psionics. I.S.P. 3D4x10.', 'Adult 12 to 20 feet (3.6 to 6.1 m) long, a quarter of it tail, about 4 feet (1.2 m) at the shoulder; 5 to 6 feet (1.5 to 1.8 m) tall in human form; hatchlings about 10% smaller', 'Adult 200 lbs (90 kg) in human form, 1000 lbs (450 kg) as a serpent; hatchlings about 20% lighter', '6000 years', 'Worldwide but rarely recognized; on Rifts Earth notably the British Isles (the Nog Henge and Prrcyvel at New Camelot), the New German Republic, Egypt and Africa, and China', 'Humans and others it judges deserving, to whom it may grant tattoos; good Chiang-Ku aid champions against evil', 'The Splugorth, who misuse tattoo magic to enslave humans', 'Chiang-Ku Dragon R.C.C. (p.48-50), stats for both adult and hatchling; uses the Dragon experience table. Typical gear is little more than clothes, one energy pistol, a pair of ancient weapons and 2D6x100 credits in gems or gold. Cybernetics: none, incompatible. The Rifts row for this book; the Palladium Fantasy Chiang-Ku (Dragons and Gods) is chiang-ku-dragon.', 'In its true shape a green, emerald-scaled lizard on six legs with a stubby tail, a slender angular head full of spiked teeth and triangular scales; its front legs serve as arms and all six feet have three prehensile toes, an opposable thumb and black claws. It spends most of its life disguised in another shape and works quietly, behind false identities. Evil Chiang-Ku brew the Elixir of Power and Deceit (p.49-50), which grants a short-lived super ability for two weeks while making each drinker more and more the maker''s thrall, until nine drinks (six for a maker of M.A. 20 or more) leave them wholly obedient; the spell breaks only if the maker drinks his own brew.', 'Rifts World Book 3: England p.48-50');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'temporal-raider', 'Light energy blast', '2D6', 1, '1000 ft (305 m) from the hands, 500 ft (153 m) from eyes or mouth', 'Set to 1D4, 1D6 or 2D6 M.D.; up to ten a melee, two counting as one attack, in place of or mixed with hand to hand. +6 to strike.', 0),
('creature', 'temporal-raider', 'Heavy energy blast', '5D6', 1, '1000 ft (305 m) from the hands, 500 ft (153 m) from eyes or mouth', 'Set to 3D6 or 5D6 M.D.; up to five a melee. +6 to strike.', 1),
('creature', 'zllyphan-energy-being', 'Energy blast', '1D6x10', 1, '2000 ft (610 m)', 'Any increment up to 1D6x10 M.D.; six per melee in energy form. +6 to strike.', 0),
('creature', 'supreme-nexus-knight', 'Magic flaming sword', '4D6', 1, NULL, 'Standard issue; also carries a laser lance, an energy pistol and a silver-plated broadsword.', 0),
('creature', 'ghost-knight', 'Punch or kick', '4D6', 1, NULL, 'Supernatural strength.', 0),
('creature', 'ghost-knight', 'Laser pistol', '1D6', 1, '1000 ft (305 m)', '20 shots. Also uses a broadsword, short sword or dagger, any of which may be a vibro-blade.', 1),
('creature', 'chiang-ku-dragon-england', 'Flaming Sword tattoo', '2D6', 1, NULL, 'Marks of Heritage: an M.D.C. sword made from thin air.', 0);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 8 creatures are in' AS assertion, count(*) AS got, 8 AS want
  FROM creatures WHERE slug IN ('temporal-raider', 'zllyphan-energy-being', 'supreme-nexus-knight', 'ghost-knight', 'fomorian', 'ogeeyin', 'ogeeyin-guardian', 'chiang-ku-dragon-england');
SELECT 'and 3 of them are playable' AS assertion, count(*) AS got, 3 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('temporal-raider', 'zllyphan-energy-being', 'supreme-nexus-knight', 'ghost-knight', 'fomorian', 'ogeeyin', 'ogeeyin-guardian', 'chiang-ku-dragon-england');
SELECT 'the creatures carry 7 attacks' AS assertion, count(*) AS got, 7 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('temporal-raider', 'zllyphan-energy-being', 'supreme-nexus-knight', 'ghost-knight', 'fomorian', 'ogeeyin', 'ogeeyin-guardian', 'chiang-ku-dragon-england');

